package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class ImportedJournalsAcceptance {
 static String route(String id){return "/api/openservice/imported-history/sc_request/"+id;}
 static Map<String,Object> entry(String record,String journal,String kind){return map("sys_id",journal,"name","incident","element_id",record,"element",kind,"value",kind+" preserved <script>source</script>\n  exact spacing ","sys_created_by","source.author","sys_created_on","2025-02-03 04:05:06");}
 static Map<String,Object> plan(){return map("source",MigrationSource.origin(),"tables",map("incident",map("target","sc_request","fields",map("short_description","short_description","description","description","state","state","priority","priority"),"values",map("state",map("1","open")))),"history",true);}
 static void seed(String record,String comment,String note){MigrationSource.reset();MigrationSource.tables.put("incident",List.of(map("sys_id",record,"short_description","Imported service request","description","Retained source context","state","1","priority","3")));MigrationSource.tables.put("sys_journal_field",List.of(entry(record,comment,"comments"),entry(record,note,"work_notes")));MigrationSource.tables.put("sys_audit",List.of());}
 static Map<String,Object> post(WorkflowSupport h,String path,Object body,int code)throws Exception{return TransferAcceptance.result(h.json("POST",path,body,auth("admin")),code);}
 static Map<String,Object> setup(WorkflowSupport h)throws Exception{String record=id(),comment=id(),note=id();seed(record,comment,note);String job=post(h,TransferAcceptance.API,plan(),201).get("job_id").toString();TransferAcceptance.fetch(h,job);post(h,TransferAcceptance.API+"/"+job+"/preview",map(),200);post(h,TransferAcceptance.API+"/"+job+"/apply",map(),200);return map("record",record,"comment",comment,"note",note,"job",job);}
 static Map<String,Object> review(WorkflowSupport h,Map<String,Object> f,String journal)throws Exception{return object(post(h,route(f.get("record").toString()),map("operation","review","job_id",f.get("job"),"journal_id",f.get(journal)),200).get("review"));}
 static Map<String,Object> publish(Map<String,Object> review){return map("operation","publish","job_id",review.get("job_id"),"journal_id",review.get("journal_id"),"review",review.get("review"),"confirm",true);}
 static Map<String,Object> page(WorkflowSupport h,String path,String user)throws Exception{return TransferAcceptance.result(h.get(path,auth(user)),200);}
 static void run(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record);h.account("JournalReader","reader");h.account("JournalStaff","agent");h.account("JournalRequester","requester");assertEquals(404,h.get(path,auth("JournalReader")).statusCode());var review=review(h,f,"comment");assertEquals("comments",review.get("kind"));assertTrue(review.get("audience").toString().startsWith("All users"));assertEquals(false,review.get("already_published"));assertTrue(objects(page(h,path,"admin").get("entries")).isEmpty());var published=post(h,path,publish(review),200);var entry=objects(published.get("entries")).getFirst();assertEquals(ImportedJournalsAcceptance.entry(record,f.get("comment").toString(),"comments").get("value"),entry.get("body"));assertEquals("source.author",entry.get("reported_author"));assertEquals("2025-02-03 04:05:06",entry.get("reported_time"));assertEquals(MigrationSource.origin(),entry.get("source_url"));post(h,path,publish(review),200);assertEquals(true,review(h,f,"comment").get("already_published"));var note=review(h,f,"note");assertTrue(note.get("audience").toString().startsWith("Staff"));post(h,path,publish(note),200);assertEquals(2,objects(page(h,path,"admin").get("entries")).size());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","workspace","owner_id",""));db.update("INSERT INTO os_requester_record(record_id,user_id) VALUES(?,?)",record,RecordAccess.owner(db,"JournalRequester"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action IN ('comment','note')",record));String audit=JSON.writeValueAsString(db.all("SELECT * FROM os_security_event WHERE action='migration.journal_published'"));assertFalse(audit.contains("preserved"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='migration.journal_published'"));db.connection.commit();}
  for(String user:List.of("JournalReader","JournalRequester")){var visible=objects(page(h,path,user).get("entries"));assertEquals(1,visible.size());assertEquals("comments",visible.getFirst().get("kind"));assertFalse(JSON.writeValueAsString(visible).contains("work_notes"));}assertEquals(2,objects(page(h,path,"JournalStaff").get("entries")).size());new Store(h.environment);assertEquals(2,objects(page(h,path,"admin").get("entries")).size());assertEquals(200,h.get("/record/sc_request/"+record+"/imported-history",auth("JournalReader")).statusCode());
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","private","owner_id",actor));db.connection.commit();}for(String user:List.of("JournalReader","JournalRequester","JournalStaff"))assertEquals(404,h.get(path,auth(user)).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record),form="/record/sc_request/"+record+"/imported-history";h.account("JournalAgent","agent");assertEquals(401,h.get(path,null).statusCode());assertEquals(404,h.get(route(id()),auth("admin")).statusCode());assertEquals(405,h.json("PUT",path,map(),auth("admin")).statusCode());for(String query:List.of("?x=y","?after=-1","?after=bad","?after=2147483648","?after=1&after=2"))assertEquals(400,h.get(path+query,auth("admin")).statusCode());assertEquals(400,h.json("POST",path+"?after=0",map(),auth("admin")).statusCode());assertEquals(403,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",f.get("comment")),auth("JournalAgent")).statusCode());assertEquals(403,h.form(form,map("operation","review","job_id",f.get("job"),"journal_id",f.get("comment")),auth("admin")).statusCode());
  for(var body:List.of(map(),map("operation","unknown"),map("operation","review"),map("operation","review","job_id","bad","journal_id",f.get("comment")),map("operation","review","job_id",f.get("job"),"journal_id","bad"),map("operation","review","job_id",f.get("job"),"journal_id",f.get("comment"),"extra",true)))assertEquals(400,h.json("POST",path,body,auth("admin")).statusCode());assertEquals(404,h.json("POST",path,map("operation","review","job_id",id(),"journal_id",f.get("comment")),auth("admin")).statusCode());assertEquals(404,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",id()),auth("admin")).statusCode());var reviewed=review(h,f,"comment");var bad=publish(reviewed);bad.put("confirm",false);assertEquals(400,h.json("POST",path,bad,auth("admin")).statusCode());bad=publish(reviewed);bad.put("review","bad");assertEquals(409,h.json("POST",path,bad,auth("admin")).statusCode());assertEquals(200,h.protectedForm(form,map("operation","review","job_id",f.get("job"),"journal_id",f.get("comment")),auth("admin")).statusCode());bad=publish(reviewed);bad.put("confirm","false");assertEquals(400,h.protectedForm(form,bad,auth("admin")).statusCode());bad.put("confirm","true");assertEquals(200,h.protectedForm(form,bad,auth("admin")).statusCode());
 }
 static void sourceShapes(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record),journal=f.get("comment").toString();var original=entry(record,journal,"comments");for(var field:List.of(Map.entry("name","Bad table"),Map.entry("sys_id",id()),Map.entry("element_id",id()),Map.entry("name","unmapped"),Map.entry("element","secret_notes"),Map.entry("value",map()),Map.entry("value"," "),Map.entry("value","x".repeat(65537)),Map.entry("sys_created_by",""),Map.entry("sys_created_on","x".repeat(81)))){var changed=new LinkedHashMap<>(original);changed.put(field.getKey(),field.getValue());try(var db=h.store.open()){db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_id=?",JSON.writeValueAsString(changed),f.get("job"),journal);db.connection.commit();}assertEquals(400,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",journal),auth("admin")).statusCode(),field.getKey());}try(var db=h.store.open()){db.update("UPDATE os_transfer_item SET data="+db.jsonParameter()+" WHERE job_id=? AND source_id=?",JSON.writeValueAsString(original),f.get("job"),journal);db.connection.commit();}
  Map<String,Object> staged;try(var db=h.store.open()){staged=db.one("SELECT data FROM os_transfer_item WHERE job_id=? AND source_table='incident'",f.get("job"));db.update("DELETE FROM os_transfer_item WHERE job_id=? AND source_table='incident'",f.get("job"));db.connection.commit();}assertEquals(400,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",journal),auth("admin")).statusCode());try(var db=h.store.open()){db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data) VALUES(?,'incident',?,"+db.jsonParameter()+")",f.get("job"),record,JSON.writeValueAsString(staged.get("data")));db.connection.commit();}
  Map<String,Object> savedJob,savedLink;try(var db=h.store.open()){savedJob=TransferJobs.job(db,f.get("job").toString());savedLink=db.one("SELECT * FROM os_transfer_link WHERE source_url=? AND source_table='incident' AND source_id=?",MigrationSource.origin(),record);}
  for(int n=0;n<6;n++){try(var db=h.store.open()){var job=TransferJobs.job(db,f.get("job").toString());var definition=object(job.get("definition"));var detail=object(job.get("detail"));switch(n){case 0->detail.put("status","review");case 1->definition.put("history",false);case 2->object(object(definition.get("tables")).get("incident")).put("target","incident");case 3->db.update("DELETE FROM os_transfer_link WHERE source_url=? AND source_id=?",MigrationSource.origin(),record);case 4->db.update("UPDATE os_transfer_link SET target_id=? WHERE source_url=? AND source_id=?",id(),MigrationSource.origin(),record);case 5->{var link=object(savedLink.get("detail"));link.put("kind","account");db.update("UPDATE os_transfer_link SET detail="+db.jsonParameter()+" WHERE source_url=? AND source_id=?",JSON.writeValueAsString(link),MigrationSource.origin(),record);}}db.update("UPDATE os_transfer_job SET definition="+db.jsonParameter()+",detail="+db.jsonParameter()+" WHERE job_id=?",JSON.writeValueAsString(definition),JSON.writeValueAsString(detail),f.get("job"));db.connection.commit();}assertEquals(400,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",journal),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_transfer_job SET definition="+db.jsonParameter()+",detail="+db.jsonParameter()+" WHERE job_id=?",JSON.writeValueAsString(savedJob.get("definition")),JSON.writeValueAsString(savedJob.get("detail")),f.get("job"));db.update("DELETE FROM os_transfer_link WHERE source_url=? AND source_id=?",MigrationSource.origin(),record);var link=object(savedLink.get("detail"));link.put("kind","record");db.update("INSERT INTO os_transfer_link(source_url,source_table,source_id,target_id,detail) VALUES(?,'incident',?,?,"+db.jsonParameter()+")",MigrationSource.origin(),record,record,JSON.writeValueAsString(link));db.connection.commit();}}
 }
 static void changes(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record);var reviewed=review(h,f,"comment");try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.update(db,"sc_request",Service.record(db,"sc_request",record),map("description","Updated destination"),"admin","admin",null);db.connection.commit();}assertEquals(409,h.json("POST",path,publish(reviewed),auth("admin")).statusCode());reviewed=review(h,f,"comment");try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",path,publish(reviewed),auth("admin")).statusCode());reviewed=review(h,f,"comment");try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","workspace","owner_id",""));db.connection.commit();}assertEquals(409,h.json("POST",path,publish(reviewed),auth("admin")).statusCode());
  Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"sc_request");}reviewed=review(h,f,"comment");var changed=new LinkedHashMap<>(schema);changed.put("label","Renamed destination");ReferencePickerAcceptance.writeSchema(h,"sc_request",changed);assertEquals(409,h.json("POST",path,publish(reviewed),auth("admin")).statusCode());ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);String parent=h.add("incident").get("sys_id").toString();try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("INSERT INTO os_record_scope(record_id,parent_id,revision) VALUES(?,?,1)",record,parent);db.connection.commit();}reviewed=review(h,f,"comment");try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"incident",parent),actor,map("visibility","private","owner_id",actor));db.connection.commit();}assertEquals(409,h.json("POST",path,publish(reviewed),auth("admin")).statusCode());
  var request=publish(review(h,f,"comment"));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=pool.submit(()->post(h,path,request,200));var two=pool.submit(()->post(h,path,request,200));assertEquals(objects(one.get().get("entries")),objects(two.get().get("entries")));}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_imported_journal"));}for(String field:List.of("target_table","record_id","fingerprint")){try(var db=h.store.open()){db.update("UPDATE os_imported_journal SET "+field+"=?",field.equals("target_table")?"incident":"changed");db.connection.commit();}assertEquals(409,h.json("POST",path,map("operation","review","job_id",f.get("job"),"journal_id",f.get("comment")),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_imported_journal SET "+field+"=?",field.equals("target_table")?"sc_request":field.equals("record_id")?record:reviewed.get("fingerprint"));db.connection.commit();}}
 }
 static void visibilityAndPaging(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record);h.account("HistoryReader","reader");h.account("HistoryAgent","agent");post(h,path,publish(review(h,f,"comment")),200);post(h,path,publish(review(h,f,"note")),200);Map<String,Object> original;try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,"sc_request",record),actor,map("visibility","workspace","owner_id",""));original=Service.schema(db,"sc_request");db.connection.commit();}
  var changed=new LinkedHashMap<>(original);changed.put("field_rules",map("comments",map("read_roles",List.of("admin")),"work_notes",map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",changed);for(String user:List.of("HistoryReader","HistoryAgent"))assertTrue(objects(page(h,path,user).get("entries")).isEmpty());changed.put("field_rules",map("comments",map("read_roles",List.of("admin","reader","agent")),"work_notes",map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",changed);assertEquals(1,objects(page(h,path,"HistoryAgent").get("entries")).size());changed.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"sc_request",changed);assertEquals(403,h.get(path,auth("HistoryAgent")).statusCode());ReferencePickerAcceptance.writeSchema(h,"sc_request",original);
  try(var db=h.store.open()){var base=db.one("SELECT * FROM os_imported_journal WHERE kind='comments'");for(int n=0;n<55;n++)db.update("INSERT INTO os_imported_journal(source_url,journal_id,job_id,source_table,target_table,record_id,kind,body,reported_author,reported_time,fingerprint,publisher_id,published) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",base.get("source_url"),id(),base.get("job_id"),base.get("source_table"),base.get("target_table"),record,"comments","Page "+n,base.get("reported_author"),base.get("reported_time"),base.get("fingerprint"),base.get("publisher_id"),base.get("published"));db.connection.commit();}var first=page(h,path,"HistoryReader");assertEquals(50,objects(first.get("entries")).size());assertNotNull(first.get("next_after"));var second=page(h,path+"?after="+first.get("next_after"),"HistoryReader");assertEquals(6,objects(second.get("entries")).size());assertNull(second.get("next_after"));var ids=new HashSet<Object>();for(var e:objects(first.get("entries")))assertTrue(ids.add(e.get("sequence")));for(var e:objects(second.get("entries")))assertTrue(ids.add(e.get("sequence")));
 }
 static void limits(WorkflowSupport h)throws Exception{
  var f=setup(h);String record=f.get("record").toString(),path=route(record);var request=publish(review(h,f,"comment"));try(var db=h.store.open()){for(int n=0;n<1000;n++)db.update("INSERT INTO os_imported_journal(source_url,journal_id,job_id,source_table,target_table,record_id,kind,body,reported_author,reported_time,fingerprint,publisher_id,published) VALUES('fixture',?,'job','incident','sc_request',?,'comments','body','author','time','hash','actor','time')",id(),record);db.connection.commit();}assertEquals(400,h.json("POST",path,request,auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_imported_journal SET record_id='other'");for(int n=1000;n<50000;n++)db.update("INSERT INTO os_imported_journal(source_url,journal_id,job_id,source_table,target_table,record_id,kind,body,reported_author,reported_time,fingerprint,publisher_id,published) VALUES('fixture',?,'job','incident','sc_request','other','comments','body','author','time','hash','actor','time')",id());db.connection.commit();}assertEquals(400,h.json("POST",path,request,auth("admin")).statusCode());
 }
}
